build-commands:
cat << 'EOF' > /app/bin/start-jarvis
#!/bin/sh
export PYTHONPATH=/app
export NODE_ROLE=local
export JARVIS_PORT=8081
export LLM_ROUTER_BASE_URL=${LLM_ROUTER_BASE_URL:-http://localhost:20128/v1}
export LLM_ROUTER_ALLOWED_HOSTS=${LLM_ROUTER_ALLOWED_HOSTS:-localhost}
export LLM_ROUTER_MODEL=${LLM_ROUTER_MODEL:-auto/chat}
export LLM_ROUTER_FALLBACK_MODELS=${LLM_ROUTER_FALLBACK_MODELS:-}
export JARVIS_WEB_URL=${JARVIS_WEB_URL:-http://127.0.0.1:8081/}
export NEXUS_URL=${NEXUS_URL:-ws://192.168.1.92:8080}
python3 /app/src/node/jarvis_tray.py
EOF
